from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 3.1 Chromosomes, genes and DNA · 9Bs.03, 9SIC.01
# =====================================================================================================
READ["3.1"] = L(
    H("Instructions for a whole person",
      "Every one of your trillions of cells contains a full set of instructions for building and running your body – about 2 m of DNA, packed into a nucleus far too small to see.",
      "How can so much information fit inside one cell?"),
    I("Chromosomes, genes and DNA",
      "Information is organised in levels, from the largest to the smallest:",
      fig={"kind": "sciFlow", "title": "From nucleus to gene", "steps": [{"t": "Nucleus", "d": "controls the cell"}, {"t": "Chromosomes", "d": "thread-like, in pairs"},
                                                                        {"t": "DNA", "d": "a double helix"}, {"t": "Genes", "d": "sections of DNA"}]},
      then=["**Chromosomes** are made of **DNA** and protein. Humans have **23 pairs (46)**, including one pair of **sex chromosomes**. Other species have their own number – a fruit fly has 8, a dog 78.",
            "A **gene** is a section of DNA that controls a characteristic (a **trait**), such as eye colour. Different forms of a gene give different versions of the trait – for example long or short fur in cats.",
            "A DNA molecule is two strands twisted round each other: a **double helix**, like a twisted ladder. When a cell divides, the chromosomes are copied so each new cell gets a full set."]),
    Y("Largest to smallest",
      mcq("s9u03r11", "Which list goes from largest to smallest?",
          [("nucleus, chromosome, gene", True, "Yes – chromosomes are in the nucleus and genes are sections of a chromosome's DNA."), ("gene, chromosome, nucleus", False, "That is smallest to largest."),
           ("chromosome, nucleus, gene", False, "Chromosomes are inside the nucleus."), ("nucleus, gene, chromosome", False, "A gene is part of a chromosome.")],
          "What is inside what?", "Nucleus contains chromosomes; chromosomes contain genes.")),
    I("Discovering DNA",
      "Our understanding of DNA was built by many scientists over almost a century.",
      table=[["Year", "Scientist(s)", "Discovery"], ["1869", "Friedrich Miescher", "found a new substance in cell nuclei ('nuclein')"],
             ["1880s–1920s", "Albrecht Kossel, Phoebus Levene", "identified DNA's chemical building blocks"], ["1944", "Avery, MacLeod and McCarty", "showed that DNA – not protein – carries hereditary information"],
             ["1952", "Rosalind Franklin", "took X-ray images of DNA (such as 'Photo 51')"], ["1953", "James Watson and Francis Crick", "built the double-helix model, using Franklin's data"],
             ["2003", "Human Genome Project", "mapped all human genes, helping find genes behind disorders such as cystic fibrosis"]],
      then=["Watson and Crick's model depended on Franklin's images – an example of scientists building on each other's work (and of a contribution that was not fully recognised at the time)."]),
    K("Key points",
      "The nucleus contains **chromosomes**, made of **DNA** and protein; humans have 23 pairs.",
      "A **gene** is a section of DNA that controls a characteristic.",
      "DNA is a **double helix**. Chromosomes are copied when cells divide.",
      "DNA's structure was found by building on many scientists' work, including Franklin, Watson and Crick."),
    book=BK(
        [("chromosome", "a thread of DNA and protein in the nucleus"), ("DNA", "the molecule that carries genetic information; a double helix"),
         ("gene", "a section of DNA that controls a characteristic"), ("trait", "a characteristic, such as eye colour")],
        [], [],
        [Ex("How many chromosomes are in a normal human body cell?", ans="46 (23 pairs)"),
         Ex("Explain the link between a chromosome, DNA and a gene.", ans="A chromosome is a long DNA molecule (with protein); a gene is a section of that DNA."),
         Ex("Describe the shape of a DNA molecule.", ans="two strands twisted together – a double helix"),
         Ex("Explain how Rosalind Franklin's work helped Watson and Crick.", ans="Her X-ray images showed the helical shape and dimensions, which their model was based on.", think=True)],
        ["describe chromosomes, genes and DNA", "describe how DNA's structure was discovered"],
        look=["from nucleus to gene", "the DNA timeline"],
        note="Read it after the video: chromosomes, genes, DNA and its discovery (answers at the back)."),
)

# =====================================================================================================
# 3.2 Inheritance and fetal development · 9Bp.01, 9Bp.02, 9Bp.08
# =====================================================================================================
READ["3.2"] = L(
    H("Boy or girl?",
      "A family has three daughters and is expecting a fourth child. A relative says 'this one is sure to be a boy'.",
      "Is that true? What decides whether a baby is a boy or a girl?"),
    I("Fertilisation and inheritance",
      "**Inheritance** is the passing of traits from parents to offspring.",
      then=["Sperm and egg cells (**gametes**) each have only **23** chromosomes – one from each pair. At **fertilisation** their nuclei join to make a **zygote** with all 46, and a new combination of DNA from both parents."]),
    I("Sex determination",
      "One pair of chromosomes decides sex: **females are XX**, **males are XY**.",
      fig={"kind": "punnett", "cells": [["XX", "XY"], ["XX", "XY"]]},
      then=["Every egg carries an X. Half of all sperm carry an X and half carry a Y. So the **father's sperm decides** the sex, and each baby has an equal (about 50%) chance of being a girl or a boy.",
            "Each pregnancy is independent – earlier children do not change the chance. The relative in 'Start here' is wrong."]),
    I("Predict, watch, explain: a coin model",
      "Toss a coin to model a sperm: heads = X (girl), tails = Y (boy).",
      table=[["Number of tosses", "Girls", "Boys"], ["10", "7", "3"], ["40", "22", "18"], ["200", "98", "102"]],
      then=["Small samples can be uneven, but with many tosses the result gets close to half and half."]),
    Y("Who decides?",
      mcq("s9u03r21", "Why does the father's sperm decide the sex of a baby?",
          [("Sperm can carry an X or a Y; every egg carries an X.", True, "Yes."), ("The father has more chromosomes.", False, "Both parents give 23."),
           ("Eggs can carry X or Y.", False, "Eggs always carry X."), ("The mother's age decides.", False, "Age does not decide sex.")],
          "Compare the sex chromosomes in eggs and sperm.", "Only sperm can carry a Y chromosome.")),
    I("How does the fetus develop?",
      "The zygote divides into a ball of cells that implants in the lining of the **uterus**. It is an **embryo** until about 9 weeks, then a **fetus**. Pregnancy lasts about **40 weeks**.",
      table=[["Structure", "Job"], ["**placenta**", "passes oxygen, nutrients and antibodies from mother to fetus; removes carbon dioxide and urea"],
             ["**umbilical cord**", "joins the fetus to the placenta"], ["**amniotic fluid** (in the amnion)", "cushions and protects the fetus"]],
      then=["One zygote splitting in two gives **identical twins**; two eggs fertilised separately give **non-identical twins**.",
            "Harmful substances can also cross the placenta, especially in the first weeks when organs form. A balanced diet with **folic acid, iron and calcium** helps; **smoking, alcohol and drugs** can cause low birth weight, birth defects or miscarriage."]),
    K("Key points",
      "Gametes have 23 chromosomes; fertilisation forms a zygote with 46.",
      "Females XX, males XY; the father's sperm (X or Y) decides sex – a 50% chance each time.",
      "Embryo → fetus; the placenta, umbilical cord and amniotic fluid support it for about 40 weeks.",
      "The mother's diet and habits affect the fetus."),
    book=BK(
        [("gamete", "a sex cell: sperm or egg"), ("fertilisation", "the joining of a sperm and egg nucleus"), ("zygote", "a fertilised egg cell"),
         ("sex chromosomes", "X and Y chromosomes that decide sex"), ("placenta", "an organ that exchanges substances between mother and fetus"), ("fetus", "an unborn baby after about 9 weeks")],
        [], [],
        [Ex("How many chromosomes are in: (a) a human egg cell (b) a zygote?", ans="(a) 23 (b) 46"),
         Ex("Complete a Punnett grid for XX × XY and give the chance of a girl.", ans="XX, XX, XY, XY → 50% girl"),
         Ex("Give two jobs of the placenta.", ans="passes oxygen and nutrients to the fetus; removes carbon dioxide and urea"),
         Ex("Explain why identical twins are always the same sex.", ans="They come from one zygote that split, so they have the same chromosomes, including the sex chromosomes."),
         Ex("Why are pregnant women advised not to smoke or drink alcohol?", ans="Harmful substances cross the placenta and can damage the fetus – low birth weight, birth defects, miscarriage.", think=True)],
        ["describe fertilisation", "explain how sex is determined", "describe how a fetus develops and how the mother's health affects it"],
        look=["the X and Y grid", "the placenta table"],
        note="Read it after the video: fertilisation, sex determination and fetal development (answers at the back)."),
)

# =====================================================================================================
# 3.3 What is variation? · 9Bp.03
# =====================================================================================================
READ["3.3"] = L(
    H("Same parents, different children",
      "Two sisters have the same parents, yet one has curly hair and brown eyes and the other straight hair and blue eyes.",
      "How can children of the same parents be so different?"),
    I("Variation",
      "**Variation** is the differences between individuals of the same species.",
      table=[["Type", "Cause", "Examples"],
             ["**inherited** (genetic)", "different combinations of genes from the parents", "eye colour, blood group, natural hair colour, earlobe shape"],
             ["**environmental**", "conditions such as diet, climate, soil, lifestyle", "scars, language spoken, muscle size from exercise, suntan, hydrangea flower colour"],
             ["**both**", "genes and environment together", "height, body mass, plant height"]],
      then=["Each gamete carries a different half-set of genes, so every zygote gets a new combination – except identical twins."]),
    Y("Inherited or environmental?",
      grid("s9u03r31", "What causes each variation?", ["Inherited", "Environmental", "Both"],
           [("blood group", "Inherited"), ("a scar on the knee", "Environmental"), ("height", "Both"), ("natural eye colour", "Inherited"), ("speaking Spanish", "Environmental")],
           "Could you change it in your lifetime?", "Blood group and eye colour are inherited; scars and languages come from the environment; height depends on both.")),
    I("Continuous and discontinuous variation",
      "Variation is either continuous or discontinuous.",
      table=[["", "Continuous", "Discontinuous"], ["values", "any value in a range", "a few distinct groups"], ["examples", "height, mass, hand span", "blood group, eye colour, tongue rolling"],
             ["graph", "histogram or line graph – often a bell shape", "bar chart with gaps"]]),
    I("Class data: heights of 30 students",
      "Heights grouped into 5 cm ranges:",
      fig={"kind": "barchart", "labels": ["140–144", "145–149", "150–154", "155–159", "160–164", "165–169"], "values": [2, 5, 9, 8, 4, 2], "ymax": 10, "step": 2,
           "ylabel": "number of students", "xlabel": "height (cm)"},
      then=["Most students are in the middle; only a few are very short or very tall – the typical shape of **continuous** variation. Height depends on genes **and** environment (diet, health)."]),
    Y("Most common",
      num("s9u03r32", "How many students are between 150 and 159 cm tall?", 17, "Add the two middle bars.", "9 + 8 = 17.")),
    K("Key points",
      "**Variation**: differences between individuals of a species.",
      "**Inherited** (genes), **environmental** (conditions) or both.",
      "**Continuous** variation (any value, e.g. height) and **discontinuous** (distinct groups, e.g. blood group)."),
    book=BK(
        [("variation", "differences between individuals of the same species"), ("inherited variation", "caused by genes"), ("environmental variation", "caused by surroundings or lifestyle"),
         ("continuous variation", "can take any value in a range"), ("discontinuous variation", "falls into distinct groups")],
        [], [],
        [Ex("Classify as continuous or discontinuous: (a) mass (b) blood group (c) foot length (d) whether you can roll your tongue.", ans="(a) continuous (b) discontinuous (c) continuous (d) discontinuous"),
         Ex("Give two examples of environmental variation in plants.", ans="e.g. height affected by light or soil; hydrangea colour depending on soil pH"),
         Ex("Use the chart: what fraction of the class is 160 cm or taller?", ans="6 out of 30 = 1/5"),
         Ex("Identical twins grow up in different countries. One is 4 cm taller. What does this tell you about height?", ans="Height is affected by environment (e.g. diet) as well as genes, since their genes are identical.", think=True)],
        ["distinguish inherited and environmental variation", "describe continuous and discontinuous variation", "interpret variation data"],
        look=["the variation table", "the heights chart"],
        note="Read it after the video: inherited and environmental variation and the height data (answers at the back)."),
)

# =====================================================================================================
# 3.4 Natural selection · 9Bp.04
# =====================================================================================================
READ["3.4"] = L(
    H("Nets that stopped working",
      "Bed nets treated with insecticide saved millions of people from malaria. But in many places they now kill far fewer mosquitoes than they used to.",
      "The nets have not changed. What could have changed in the mosquitoes?"),
    I("Predict, watch, explain: hunting camouflaged worms",
      "Ten red and ten green paper 'worms' are scattered on grass. 'Birds' (students) have one minute to pick up as many as they can. Nine red worms are found but only two green.",
      then=["The green worms are **camouflaged** against the grass. In a real population, better-camouflaged individuals survive, breed and pass on their genes, so over many generations more of the population is camouflaged."]),
    I("Natural selection",
      "Charles Darwin explained how species change over time (after studying finches on the Galápagos Islands, whose beaks suited different foods).",
      fig={"kind": "sciFlow", "title": "Natural selection", "steps": [{"t": "Variation", "d": "individuals differ"}, {"t": "Competition", "d": "more are born than can survive"},
                                                                     {"t": "Survival", "d": "the best-adapted survive"}, {"t": "Reproduction", "d": "they pass on their genes"},
                                                                     {"t": "Change", "d": "over generations, the population changes"}]},
      then=["Example: in a population of mice, owls catch the light-coloured mice more easily on dark soil. Dark mice survive and breed more, so after many generations most mice are dark.",
            "Over very long times natural selection can produce new species."]),
    I("Natural selection in action",
      "In organisms that reproduce quickly, natural selection can be seen within a few years.",
      table=[["Example", "What happens"],
             ["**antibiotic resistance**", "a few bacteria have a variation that resists an antibiotic; the antibiotic kills the rest; the resistant ones multiply – 'superbugs'"],
             ["**insecticide resistance**", "a few mosquitoes can survive the insecticide; they breed, so over generations the nets stop working"]],
      then=["That is why doctors say: only take antibiotics when needed and finish the course; and why new insecticides must keep being developed."]),
    Y("Resistance",
      mcq("s9u03r41", "Why did insecticide-treated bed nets become less effective?",
          [("Mosquitoes with resistance survived and bred, passing on resistance.", True, "Yes – natural selection."), ("The insecticide washed off every net.", False, "That is not the main reason."),
           ("Mosquitoes decided to become resistant.", False, "Individuals cannot choose their genes."), ("New mosquitoes came from other planets.", False, "No!")],
          "Which mosquitoes survived to breed?", "Resistant individuals survived and passed on their genes; over generations most became resistant.")),
    X("Organisms do not change on purpose",
      "It is tempting to say 'the bacteria learned to resist the antibiotic'.",
      "Individuals do not change their genes because they need to. The variation was already there by chance; the antibiotic simply killed the others, so the resistant ones were **selected**."),
    K("Key points",
      "Natural selection: variation → competition → survival of the best adapted → reproduction → gradual change.",
      "Darwin developed the theory; camouflage, beak shape and fur colour are examples.",
      "Antibiotic-resistant bacteria and insecticide-resistant mosquitoes show natural selection happening now."),
    book=BK(
        [("natural selection", "the process by which better-adapted individuals survive and pass on their genes"), ("camouflage", "colouring that helps an organism blend into its surroundings"),
         ("resistance", "being able to survive an antibiotic or insecticide"), ("species", "organisms that can breed to produce fertile offspring")],
        [], [],
        [Ex("List the stages of natural selection.", ans="variation; more born than survive; best-adapted survive; they reproduce and pass on genes; population changes over generations"),
         Ex("Explain how antibiotic-resistant bacteria arise.", ans="Some bacteria have a resistance variation; the antibiotic kills the others; the resistant ones multiply."),
         Ex("Why should patients finish a course of antibiotics?", ans="To kill all the bacteria, including the more resistant ones, so they cannot multiply."),
         Ex("Peppered moths are pale or dark. When trees were blackened by soot, dark moths became common. Explain using natural selection.",
            ans="Dark moths were camouflaged on sooty trees, so birds ate fewer; they survived, bred and passed on their dark colour.", think=True)],
        ["explain natural selection", "explain antibiotic and insecticide resistance"],
        look=["the five steps of natural selection", "resistance examples"],
        note="Read it after the video: natural selection and resistance (answers at the back)."),
)

# =====================================================================================================
# 3.5 Populations and environment · 9Be.01
# =====================================================================================================
READ["3.5"] = L(
    H("Rabbits on an island",
      "Twenty rabbits are released on a small island with plenty of grass and no predators.",
      "Will their population keep growing for ever? Sketch what you think a graph of their numbers would look like."),
    I("What affects population size?",
      "A population grows when births are greater than deaths. Many factors change this.",
      table=[["Factor", "Example"], ["food and water", "a drought kills grass, so grazing animals starve"], ["predators", "more lions → fewer zebras"],
             ["disease", "rinderpest killed huge numbers of buffalo"], ["natural disasters", "the asteroid that ended the dinosaurs; floods, fires, droughts"],
             ["human activity", "deforestation, coral bleaching, overfishing, pollution"]],
      then=["If a population falls to zero everywhere, the species is **extinct**."]),
    I("Data: rabbits released on an island",
      "The rabbits were counted every year.",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 8, "step": 1, "label": "time (years)"}, "y": {"min": 0, "max": 500, "step": 100, "label": "number of rabbits"},
           "series": [{"pts": [[0, 20], [1, 45], [2, 110], [3, 240], [4, 380], [5, 450], [6, 465], [7, 470], [8, 468]]}]},
      then=["Slow growth at first, then very fast growth with plenty of food and space, then the numbers **level off** at about 470.",
            "The island cannot support more rabbits: food, space and water run short. The maximum population an environment can support is its **carrying capacity**."]),
    Y("Read the graph",
      num("s9u03r51", "By how many rabbits did the population grow between year 2 and year 4?", 270, "Read both values and subtract.", "380 − 110 = 270.")),
    Y("Why level off?",
      mcq("s9u03r52", "Why did the rabbit population stop growing?",
          [("There was not enough food and space for more rabbits.", True, "Yes – the island reached its carrying capacity."), ("All the rabbits became old.", False, "Young are still born."),
           ("Predators arrived.", False, "There were no predators."), ("Rabbits stopped breeding for no reason.", False, "There is a reason: limited resources.")],
          "What limits the island?", "Food and space ran short.")),
    K("Key points",
      "Population size depends on food, water, space, predators, disease, disasters and human activity.",
      "Populations often grow slowly, then fast, then level off at the **carrying capacity**.",
      "Human activities such as deforestation, overfishing and pollution can drive species to extinction."),
    book=BK(
        [("population", "all the organisms of one species in an area"), ("carrying capacity", "the largest population an environment can support"), ("extinct", "no longer existing anywhere")],
        [], [],
        [Ex("Give three natural factors and two human factors that can reduce a population.", ans="natural: disease, drought, predators; human: deforestation, overfishing / pollution"),
         Ex("Describe the shape of the rabbit graph and explain each part.", ans="slow start (few breeding), rapid rise (plenty of resources), levels off (carrying capacity)"),
         Ex("Predict what would happen to the rabbits if foxes were brought to the island.", ans="The rabbit population would fall, then may settle at a lower level."),
         Ex("Quick quiz.", ("How many chromosomes are in a human egg cell?", "23"), ("Which parent decides the sex of a baby?", "the father"),
            ("Give one example of environmental variation.", "e.g. scars, muscle size, hydrangea colour"), ("Why did insecticide nets become less effective?", "resistant mosquitoes survived and bred")),
         Ex("Coral reefs bleach when the sea gets too warm. Explain how this could affect fish populations.", ans="Bleached corals die, so fish lose food and shelter; their populations fall.", think=True)],
        ["describe factors that change population size", "interpret population data and carrying capacity", "explain how human activity can cause extinction"],
        look=["the rabbit graph", "factors affecting populations"],
        note="Read it after the video: populations, carrying capacity and extinction, plus a quick quiz (answers at the back)."),
)
